const WRITE_PENDING_PREVIEW_STATE_KEY = "hashline-write-pending-preview";

const CONTENT_PREVIEW_MAX_LINES = 200;

function formatContentPreviewLines(content: string, theme: any): string[] {
  const lines = content.split("\n");
  // Drop the single trailing blank produced by a terminal newline so the
  // preview reads naturally.
  if (lines.length > 0 && lines[lines.length - 1] === "") lines.pop();
  const shown = lines.slice(0, CONTENT_PREVIEW_MAX_LINES);
  // Right-align line numbers so the body has a stable column for the content.
  // The dim gutter ("  N │ ") visually distinguishes the body from the
  // "↳ created / pending create" header above it without re-introducing
  // diff chrome (no +/- marker, no red/green tint).
  const width = String(shown.length).length;
  // Bind theme.fg so we keep its `this` (the Theme uses internal state); fall back
  // to an identity tint when no theme is provided (e.g. in tests).
  const fg = typeof theme?.fg === "function" ? (style: string, text: string) => theme.fg(style, text) : (_style: string, text: string) => text;
  const formatted = shown.map((line, index) => {
    const gutter = fg("dim", `${String(index + 1).padStart(width, " ")} │ `);
    return `  ${gutter}${line}`;
  });
  if (lines.length > CONTENT_PREVIEW_MAX_LINES) {
    formatted.push(`  ${fg("dim", `… ${lines.length - CONTENT_PREVIEW_MAX_LINES} more lines not shown`)}`);
  }
  return formatted;
}

function pendingWritePreviewParts(summary: string, preview: PendingDiffPreviewResult | undefined, expanded: boolean, theme: any): { lines: string[]; diffData?: DiffData } {
  if (!expanded || !preview || preview.type !== "ok") return { lines: summary.split("\n") };
  const headerLine = summaryLine(preview.data.headerLabel, { hidden: false });
  if (!preview.data.fileExistedBeforeWrite) {
    return { lines: [summary, headerLine, ...formatContentPreviewLines(preview.data.nextContent, theme)] };
  }
  const diffData = buildDiffData({
    path: preview.data.filePath,
    oldContent: preview.data.previousContent,
    newContent: preview.data.nextContent,
    diff: preview.data.diff,
  });
  return { lines: [summary, headerLine], diffData };
}

const MAX_LINES = 2000;
const MAX_BYTES = 50 * 1024;
/**
 * Visible result for writes whose anchors exceed MAX_LINES / MAX_BYTES. ASCII only: a single
 * non-Latin-1 character makes QuickJS store the whole codemode payload as 16-bit text (#273).
 */
export function formatCompactWriteSummary(displayPath: string, totalLines: number, bytes: number): string {
  return `Wrote ${displayPath} (${totalLines} ${totalLines === 1 ? "line" : "lines"}, ${bytes} bytes). `
    + `Anchors omitted for writes over ${MAX_LINES} lines or ${MAX_BYTES / 1024} KB of anchors; `
    + "use read with offset/limit to get anchors before editing.";
}
const WRITE_PROMPT_METADATA = defineToolPromptMetadata({
  promptUrl: packageFileUrl("prompts", "write.md"),
  promptSnippet: "Create or overwrite a complete file and return edit anchors",
  promptGuidelines: [
    "Use write to create new files or intentionally replace whole files.",
    "Use edit instead of write for small changes or appends to existing files.",
    "Remember write overwrites existing files without confirmation.",
  ],
});

type WriteDiffFields = {
  diff?: string;
  diffData?: DiffData;
};

export interface WriteResult extends WriteDiffFields {
  text: string;
  warnings: string[];
  writeState?: "created" | "overwritten";
  ptcValue: {
    tool: "write";
    path: string;
    lines: PtcLine[];
    warnings: PtcWarning[];
    diff?: string;
    diffData?: DiffData;
    map?: { appended: boolean };
    /** Large write: anchors, diff, and diffData omitted; use read for anchors. */
    truncated?: true;
    totalLines?: number;
    bytes?: number;
  };
  contextHygiene: ContextHygieneMetadata;
}

function readPreviousTextForDiff(filePath: string): string {
  try {
    if (!existsSync(filePath)) return "";
    const previous = readFileSync(filePath);
    if (looksLikeBinary(previous)) return "";
    return previous.toString("utf-8");
  } catch {
    return "";
  }
}

function generateWriteDiff(previousContent: string, nextContent: string): { diff: string; firstChangedLine: number | undefined } {
  if (previousContent !== "") return generateCompactOrFullDiff(previousContent, nextContent);
  const normalizedNext = normalizeToLF(nextContent);
  if (normalizedNext === "") return { diff: "", firstChangedLine: undefined };
  const lines = normalizedNext.split("\n");
  if (lines[lines.length - 1] === "") lines.pop();
  const width = String(lines.length).length;
  return {
    diff: lines.map((line, index) => `+${String(index + 1).padStart(width, " ")} ${line}`).join("\n"),
    firstChangedLine: 1,
  };
}

export interface WriteToolOptions {
  onFileAnchored?: (absolutePath: string, mark?: { own: boolean }) => void;
}

type MappedFsError = {
  code: "permission-denied" | "path-is-directory" | "fs-error";
  message: string;
  includeMeta: boolean;
};

function mapFsWriteError(err: any, path: string): MappedFsError {
  const phase: "mkdir" | "write" | undefined = err?.__phase;
  const fsCode = err?.code as string | undefined;

  if (fsCode === "EACCES" || fsCode === "EPERM") {
    return {
      code: "permission-denied",
      message: `Permission denied — cannot write: ${path}`,
      includeMeta: false,
    };
  }
  if (fsCode === "EISDIR") {
    return {
      code: "path-is-directory",
      message: `Path is a directory — cannot overwrite: ${path}`,
      includeMeta: false,
    };
  }
  if (fsCode === "ENOENT" && phase === "mkdir") {
    return {
      code: "fs-error",
      message: `Cannot create parent directories for ${path}: ${err?.message ?? String(err)}`,
      includeMeta: true,
    };
  }
  if (fsCode === "ENOSPC") {
    return {
      code: "fs-error",
      message: `No space left on device — cannot write: ${path}`,
      includeMeta: true,
    };
  }
  if (fsCode === "EROFS") {
    return {
      code: "fs-error",
      message: `Read-only filesystem — cannot write: ${path}`,
      includeMeta: true,
    };
  }
  return {
    code: "fs-error",
    message: `Error writing ${path}: ${err?.message ?? String(err)}`,
    includeMeta: true,
  };
}

export async function executeWrite(opts: {
  path: string;
  content: string;
  map?: boolean;
  cwd?: string;
}): Promise<WriteResult> {
  await ensureHashInit();

  const { path: filePath, content, map: requestMap, cwd } = opts;
  const warnings: string[] = [];
  const ptcWarnings: PtcWarning[] = [];
  const contextHygiene = buildContextHygieneMetadata({
    tool: "write",
    classification: "mutation",
    resources: [buildFileResource(filePath)],
  });

  if (hasBareCarriageReturn(content)) {
    const message = "File content contains bare CR (\\r) line endings; write refuses to emit anchors that read/edit would normalize differently.";
    warnings.push(message);
    ptcWarnings.push(buildPtcWarning("bare-cr", message));
    return {
      text: `Cannot write ${filePath}\n⚠️ ${message}`,
      warnings,
      ptcValue: {
        tool: "write",
        path: filePath,
        lines: [],
        warnings: ptcWarnings,
      },
      contextHygiene,
    };
  }
  const previousContent = readPreviousTextForDiff(filePath);
  const existedBeforeWrite = existsSync(filePath);

  // Atomic write (handles parent-dir creation, symlinks, hard links)
  try {
    await writeFileAtomically(filePath, content);
  } catch (err: any) {
    err.__phase = "write";
    throw err;
  }


  // Binary detection
  if (looksLikeBinary(Buffer.from(content, "utf-8"))) {
    warnings.push("File content appears to be binary.");
    ptcWarnings.push(buildPtcWarning("binary-content", "File content appears to be binary."));
    return {
      text: `Wrote ${filePath}\n⚠️ File content appears to be binary — hashlines not generated.`,
      warnings,
      writeState: existedBeforeWrite ? "overwritten" : "created",
      ptcValue: {
        tool: "write",
        path: filePath,
        lines: [],
        warnings: ptcWarnings,
      },
      contextHygiene,
    };
  }

  const displayPath = cwd ? relative(cwd, filePath) || filePath : filePath;
  const writeState: "created" | "overwritten" = existedBeforeWrite ? "overwritten" : "created";

  // Compute hashlines. Writes whose anchors would exceed the visible budget return a
  // compact summary and a bounded structured value instead (#273).
  const rawLines = splitDisplayLines(content);
  const ptcLines: PtcLine[] = [];
  let text = "";
  let compact = rawLines.length > MAX_LINES;
  if (!compact) {
    const displayLines: string[] = [];
    for (let i = 0; i < rawLines.length; i++) {
      const lineNum = i + 1;
      ptcLines.push(buildPtcLine(lineNum, rawLines[i]));
      displayLines.push(formatHashlineDisplay(lineNum, rawLines[i]));
    }
    text = displayLines.join("\n");
    compact = Buffer.byteLength(text, "utf8") > MAX_BYTES;
  }
  const contentBytes = Buffer.byteLength(content, "utf8");
  if (compact) {
    ptcLines.length = 0;
    text = formatCompactWriteSummary(displayPath, rawLines.length, contentBytes);
    const omittedMessage = `Anchors omitted: ${rawLines.length} lines exceed the write anchor budget (${MAX_LINES} lines / ${MAX_BYTES / 1024} KB); use read with offset/limit for anchors.`;
    warnings.push(omittedMessage);
    ptcWarnings.push(buildPtcWarning("anchors-omitted", omittedMessage));
  }

  // Optional structural map
  let mapAppended = false;
  if (requestMap) {
    try {
      const fileMap = await getOrGenerateMap(filePath);
      if (fileMap) {
        const mapText = formatFileMapWithBudget(fileMap);
        if (mapText) {
          text += "\n\n" + mapText;
          mapAppended = true;
        }
      }
    } catch {
      // Map generation failure is non-fatal
    }

[271 more lines in file. Use offset=301 to continue.]

	absolutePath: string;
	displayPath: string;
	result: string;
	bom: string;
	originalEnding: ReturnType<typeof detectLineEnding>;
	postEditVerify: boolean;
	physicalResult?: string;
}): Promise<EditPhaseResult<{ writeContent: string }>> {
	const writeContent = input.bom + (input.physicalResult ?? restoreLineEndings(input.result, input.originalEnding));
	try {
		await writeFileAtomically(input.absolutePath, writeContent);
	} catch (err: any) {
		const wrapped = wrapWriteError(err, input.displayPath);
		const code =
			err?.code === "EACCES" || err?.code === "EPERM"
				? "permission-denied"
				: err?.code === "ENOENT"
					? "file-not-found"
					: "fs-error";
		const message = code === "fs-error" && err?.message ? `${wrapped.message} — ${err.message}` : wrapped.message;
		return buildEditError(
			input.absolutePath,
			code,
			message,
			undefined,
			code === "fs-error" ? { fsCode: err?.code, fsMessage: err?.message } : undefined,
		);
	}

	if (!input.postEditVerify) return { writeContent };
	const contextHygiene = buildContextHygieneMetadata({
		tool: "edit",
		classification: "mutation",
		resources: [buildFileResource(input.absolutePath)],
	});
	let verifiedContent: string;
	try {
		verifiedContent = await fsReadFile(input.absolutePath, "utf-8");
	} catch (err: any) {
		return buildEditError(
			input.absolutePath,
			"post-edit-verification-read-failed",
			`Edit write completed but post-edit verification failed: could not read ${input.displayPath} after writing.`,
			undefined,
			{ fsCode: err?.code, fsMessage: err?.message },
			contextHygiene,
		);
	}
	if (verifiedContent !== writeContent) {
		return buildEditError(
			input.absolutePath,
			"post-edit-verification-mismatch",
			`Edit write completed but post-edit verification did not confirm the intended content for ${input.displayPath}. Re-read the file before making follow-up edits.`,
			undefined,
			{ expectedLength: writeContent.length, actualLength: verifiedContent.length },
			contextHygiene,
		);
	}
	return { writeContent };
}

type EditSuccessResult = {
	content: Array<{ type: "text"; text: string }>;
	details: EditToolDetails & {
		diffData: ReturnType<typeof buildDiffData>;
		ptcValue: ReturnType<typeof buildEditOutput>["ptcValue"];
		contextHygiene: ContextHygieneMetadata;
	};
};

async function buildEditResult(input: {
	absolutePath: string;
	displayPath: string;
	originalNormalized: string;
	result: string;
	physicalOriginal?: string;
	physicalResult?: string;
	probes: ReplaceSymbolProbe[];
	anchorResult: AnchorEditResult;
	edits: EditItem[];
	legacyNormalizationWarning?: string;
	replaceWarnings: string[];
	replaceSymbolWarnings: string[];
	syntaxWarning?: string;
	/** Notes about lines a cross-file move_lines removed from its source file. */
	moveNotes?: string[];
	/** Notes about anchors remapped through an earlier edit that moved their lines. */
	anchorNotes?: string[];
}): Promise<EditSuccessResult> {
	const diffResult = generateCompactOrFullDiff(input.originalNormalized, input.result);
	const patch = createPatch(input.displayPath, input.physicalOriginal ?? input.originalNormalized, input.physicalResult ?? input.result);
	const blockRanges: DiffBlockRange[] = input.probes.map((probe) => ({
		kind: "remove" as const,
		startLine: probe.range.start,
		endLine: probe.range.end,
	}));
	const diffData = buildDiffData({
		path: input.absolutePath,
		oldContent: input.originalNormalized,
		newContent: input.result,
		diff: diffResult.diff,
		...(blockRanges.length ? { blockRanges } : {}),
	});
	const warnings: string[] = [];
	if (input.anchorResult.warnings?.length) warnings.push(...input.anchorResult.warnings);
	if (input.anchorNotes?.length) warnings.push(...input.anchorNotes);
	if (input.legacyNormalizationWarning) warnings.push(input.legacyNormalizationWarning);
	if (input.replaceWarnings.length) warnings.push(...input.replaceWarnings);
	if (input.replaceSymbolWarnings.length) warnings.push(...input.replaceSymbolWarnings);
	if (input.syntaxWarning) warnings.push(input.syntaxWarning);
	if (input.moveNotes?.length) warnings.push(...input.moveNotes);

	const internalClassification = classifyEdit(input.originalNormalized, input.result);
	const difftAvailable = await isDifftAvailable();
	let semanticSummary: SemanticSummary = {
		classification: internalClassification.classification,
		difftasticAvailable: difftAvailable,
	};
	if (difftAvailable) {
		const extension = input.displayPath.split(".").pop() ?? "txt";
		const difftResult = await runDifftastic(input.originalNormalized, input.result, extension);
		if (difftResult) {
			semanticSummary = {
				classification: difftResult.classification,
				difftasticAvailable: true,
				...(difftResult.movedBlocks > 0 ? { movedBlocks: difftResult.movedBlocks } : {}),
			};
		}
	}

	const builtOutput = buildEditOutput({
		path: input.absolutePath,
		displayPath: input.displayPath,
		diff: diffResult.diff,
		patch,
		diffData,
		firstChangedLine: input.anchorResult.firstChangedLine ?? diffResult.firstChangedLine,
		warnings,
		noopEdits: input.anchorResult.noopEdits ?? [],
		edits: input.edits,
		semanticSummary,
	});
	return {
		content: [{ type: "text", text: builtOutput.text }],
		details: {
			diff: diffResult.diff,
			patch: builtOutput.patch,
			diffData,
			firstChangedLine: input.anchorResult.firstChangedLine ?? diffResult.firstChangedLine,
			ptcValue: builtOutput.ptcValue,
			contextHygiene: builtOutput.contextHygiene,
		} as EditSuccessResult["details"],
	};
}

// ─── Registration ───────────────────────────────────────────────────────

export function registerEditTool(pi: ExtensionAPI, options: EditToolOptions = {}) {
	const tool = {
		name: "edit",
		label: "Edit",
		// Pi runs a whole batch in call order when any call in it is sequential: a read after an edit sees the write.
		executionMode: "sequential" as const,
		description: EDIT_PROMPT_METADATA.description,
		promptSnippet: EDIT_PROMPT_METADATA.promptSnippet,
		promptGuidelines: EDIT_PROMPT_METADATA.promptGuidelines,
		parameters: hashlineEditSchema,
		// edit's schema fails strict conversion, so the host sends it non-strict, as it does the built-in.
		constrainedSampling: { type: "json_schema", strict: "prefer" } as const,
		renderShell: "default" as const,
		async execute(_toolCallId, params, signal, _onUpdate, ctx) {
			const normalized = normalizeToolParameters(hashlineEditSchema, params);
			if (normalized.requiredNull) {
				return buildRequiredNullParameterError("edit", normalized.requiredNull);
			}
			const parsed = normalized.value as HashlineParams;
			const input = normalized.value as Record<string, unknown>;
			await ensureHashInit();
			const rawPath = parsed.path;
			const path = rawPath.replace(/^@/, "");
			const absolutePath = resolveToCwd(path, ctx.cwd);
			throwIfAborted(signal);
			try {
				const queueKey = await resolveMutationTargetPath(absolutePath);
				return await withFileMutationQueue(queueKey, async () => {
					throwIfAborted(signal);
					const validated = validateEdits({ parsed, rawInput: input, absolutePath, signal });
					if (isEditErrorResult(validated)) return validated;
					const { edits, anchorEdits: requestedAnchorEdits, replaceEdits, replaceSymbolEdits, legacyNormalizationWarning } = validated;
					const notRead = requireReadForAnchors(options, absolutePath, rawPath, requestedAnchorEdits.length + replaceSymbolEdits.length > 0);
					if (notRead) return notRead;

					const loaded = await loadEditSource({ absolutePath, displayPath: path, signal });
					if (isEditErrorResult(loaded)) return loaded;
					const { bom, originalEnding, originalNormalized, originalContent } = loaded;
					const shifted = remapShiftedAnchors({ served: options.served, path: absolutePath, currentLines: originalNormalized.split("\n"), edits: requestedAnchorEdits });
					if (!shifted.ok) return recordErrorFeedback(options, absolutePath, buildEditError(absolutePath, "hash-mismatch", shifted.message, undefined, { updatedAnchors: shifted.rows }));
					const anchorEdits = shifted.edits;
					const preserveLineEndings = true;

					const resolvedSymbols = await resolveReplaceSymbols({
						absolutePath,
						originalNormalized,
						replaceSymbolEdits,
					});
					if (isEditErrorResult(resolvedSymbols)) return resolvedSymbols;

					const symbolOverlapError = validateReplaceSymbolOverlaps({
						absolutePath,
						probes: resolvedSymbols,
						anchorEdits,
					});
					if (symbolOverlapError) return symbolOverlapError;

					const symbolApplication = applyResolvedReplaceSymbols(originalContent, resolvedSymbols, true);
					const rsProbeResults = resolvedSymbols;
					const replaceSymbolWarnings = symbolApplication.warnings;
					let result = symbolApplication.content;

					const anchorResult = await applyAnchorEdits({ absolutePath, content: result, anchorEdits, cwd: ctx.cwd, signal, preserveLineEndings });
					if (isEditErrorResult(anchorResult)) return recordErrorFeedback(options, absolutePath, anchorResult);
					result = anchorResult.content;

					const replacementResult = applyReplaceEdits({
						absolutePath,
						displayPath: path,
						content: result,
						replaceEdits,
						signal,
						preserveLineEndings,
					});
					if (isEditErrorResult(replacementResult)) return recordErrorFeedback(options, absolutePath, replacementResult);
					result = replacementResult.content;
					const normalizedResult = normalizeToLF(result);
					const replaceWarnings = replacementResult.warnings;

					const noopError = detectNoop({
						absolutePath,
						displayPath: path,
						originalNormalized: preserveLineEndings ? originalContent : originalNormalized,
						result,
						edits,
						anchorResult,
					});
					if (noopError) return noopError;

					const retype = await findCorruptedRetype({ edits: anchorEdits, absolutePath, currentContent: originalNormalized, candidatePaths: options.served?.paths() ?? [], cwd: ctx.cwd });
					if (retype) return buildEditError(absolutePath, "corrupted-retype", retype.message);
					const staleError = rejectStaleOverwrites(options.served, absolutePath, originalNormalized, normalizedResult, originalContent, result);
					if (staleError) options.onFileAnchored?.(absolutePath);
					if (staleError) return staleError;
					const sourceRemovals = await planSourceRemovals({ anchorEdits, absolutePath, cwd: ctx.cwd, options, signal });
					if (isEditErrorResult(sourceRemovals)) return sourceRemovals;

					throwIfAborted(signal);

					const syntaxResult = await validateEditSyntax({
						absolutePath,
						originalNormalized,
						result: normalizedResult,
						syntaxValidate: options.syntaxValidate,
					});
					if (isEditErrorResult(syntaxResult)) return syntaxResult;
					const syntaxWarning = syntaxResult.warning;

					const writeResult = await finalizeWrite({
						absolutePath,
						displayPath: path,
						result,
						bom,
						originalEnding,
						postEditVerify: input.postEditVerify === true,
						physicalResult: preserveLineEndings ? result : undefined,
					});
					if (isEditErrorResult(writeResult)) return writeResult;
					const shift = options.served?.remapAfterWrite(absolutePath, originalNormalized.split("\n"), normalizedResult.split("\n"), replaceEdits.length || replaceSymbolEdits.length ? undefined : anchorResult.lineMap);
					// This write's shifts are remapped above, so a view that was fresh before it stays fresh.
					if (options.wasReadInSession?.(absolutePath)) options.onFileAnchored?.(absolutePath, { own: true });
					const moveNotes = await commitSourceRemovals(sourceRemovals, options, path);
					if (isEditErrorResult(moveNotes)) return moveNotes;

